import{_ as a,c as t,o as r,ag as i}from"./chunks/framework.CMajxlqO.js";const h=JSON.parse('{"title":"HMI-inställningar","description":"","frontmatter":{},"headers":[],"relativePath":"03-konfiguration/hmi-installningar.md","filePath":"03-konfiguration/hmi-installningar.md","lastUpdated":1768315788000}'),e={name:"03-konfiguration/hmi-installningar.md"};function l(o,n,s,g,d,u){return r(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="hmi-installningar" tabindex="-1">HMI-inställningar <a class="header-anchor" href="#hmi-installningar" aria-label="Permalink to &quot;HMI-inställningar&quot;">​</a></h1><p>En HMI-panel (Human-Machine Interface) är operatörens fönster till din automationslösning. Korrekt konfiguration av HMI:n säkerställer smidig kommunikation med PLC:n och optimal användarupplevelse. Här går vi igenom de grundläggande inställningarna.</p><h2 id="oppna-hmi-konfigurationen" tabindex="-1">Öppna HMI-konfigurationen <a class="header-anchor" href="#oppna-hmi-konfigurationen" aria-label="Permalink to &quot;Öppna HMI-konfigurationen&quot;">​</a></h2><ol><li>I projektträdet, expandera din HMI-panel</li><li>Dubbelklicka på <strong>Device configuration</strong></li><li>Du ser HMI-panelens hårdvarukonfiguration</li></ol><h2 id="grundlaggande-installningar" tabindex="-1">Grundläggande inställningar <a class="header-anchor" href="#grundlaggande-installningar" aria-label="Permalink to &quot;Grundläggande inställningar&quot;">​</a></h2><h3 id="display-installningar" tabindex="-1">Display-inställningar <a class="header-anchor" href="#display-installningar" aria-label="Permalink to &quot;Display-inställningar&quot;">​</a></h3><p>Markera HMI-panelen och öppna <strong>Properties</strong>:</p><h4 id="skarmupplosning-och-orientering" tabindex="-1">Skärmupplösning och orientering <a class="header-anchor" href="#skarmupplosning-och-orientering" aria-label="Permalink to &quot;Skärmupplösning och orientering&quot;">​</a></h4><ol><li>Under <strong>General</strong> → <strong>Display</strong></li><li><strong>Screen orientation:</strong><ul><li>Landscape (liggande) - standard</li><li>Portrait (stående) - för vertikala paneler</li></ul></li><li>Upplösning är förinställd baserat på panelmodell</li></ol><h4 id="bakgrundsbelysning" tabindex="-1">Bakgrundsbelysning <a class="header-anchor" href="#bakgrundsbelysning" aria-label="Permalink to &quot;Bakgrundsbelysning&quot;">​</a></h4><ol><li>Under <strong>Runtime settings</strong> → <strong>Screens</strong> → <strong>General</strong></li><li><strong>Backlight timing:</strong><ul><li>Tid innan skärmen dimmas (t.ex. 10 min)</li><li>Dimningsnivå (20-100%)</li><li>Användbart för energibesparing</li></ul></li><li><strong>Screen saver:</strong><ul><li>Aktivera skärmsläckare efter inaktivitet</li><li>Förhindrar burn-in på skärmen</li></ul></li></ol><h3 id="sprak-och-tangentbord" tabindex="-1">Språk och tangentbord <a class="header-anchor" href="#sprak-och-tangentbord" aria-label="Permalink to &quot;Språk och tangentbord&quot;">​</a></h3><ol><li>Under <strong>Runtime settings</strong> → <strong>Language &amp; Font</strong></li><li><strong>User interface language:</strong> Svenska, Engelska, etc.</li><li><strong>Keyboard layout:</strong> Svenska (QWERTY)</li><li><strong>Text direction:</strong> Left-to-right (standard)</li></ol><div class="tip custom-block"><p class="custom-block-title">Flerspråkighet</p><p>TIA Portal stöder flera språk samtidigt! Du kan skapa texter på svenska, engelska och tyska i samma projekt och låta operatören välja.</p></div><h2 id="anslutning-till-plc" tabindex="-1">Anslutning till PLC <a class="header-anchor" href="#anslutning-till-plc" aria-label="Permalink to &quot;Anslutning till PLC&quot;">​</a></h2><h3 id="skapa-kontrollera-connection" tabindex="-1">Skapa/kontrollera connection <a class="header-anchor" href="#skapa-kontrollera-connection" aria-label="Permalink to &quot;Skapa/kontrollera connection&quot;">​</a></h3><p>HMI:n måste ha en aktiv anslutning till PLC:n:</p><ol><li>I projektträdet, expandera HMI → <strong>Connections</strong></li><li>Du bör se en anslutning till PLC:n (skapas automatiskt vid drag-drop i Network View)</li><li>Om ingen finns: Högerklicka <strong>Connections</strong> → <strong>Add new connection</strong></li></ol><h3 id="konfigurera-connection" tabindex="-1">Konfigurera connection <a class="header-anchor" href="#konfigurera-connection" aria-label="Permalink to &quot;Konfigurera connection&quot;">​</a></h3><ol><li>Dubbelklicka på connection</li><li><strong>Connection parameters:</strong><ul><li><strong>Partner:</strong> Din PLC (ska vara förvald)</li><li><strong>Connection type:</strong> S7 connection (standard för S7-1200)</li><li><strong>Interface:</strong> PN/IE (PROFINET)</li></ul></li><li><strong>Address details:</strong><ul><li>Kontrollera att rätt IP-adresser används</li><li>HMI: <code>192.168.0.20</code> → PLC: <code>192.168.0.10</code> (exempel)</li></ul></li></ol><h3 id="testa-anslutningen" tabindex="-1">Testa anslutningen <a class="header-anchor" href="#testa-anslutningen" aria-label="Permalink to &quot;Testa anslutningen&quot;">​</a></h3><ol><li>Gå online med projektet</li><li>I <strong>Online &amp; Diagnostics</strong> → <strong>Functions</strong> → <strong>Test connection</strong></li><li>Välj HMI-anslutning och klicka <strong>Ping</strong></li><li>Grön respons = OK, Röd = Problem med nätverk/IP</li></ol><h2 id="ethernet-och-ip-konfiguration" tabindex="-1">Ethernet- och IP-konfiguration <a class="header-anchor" href="#ethernet-och-ip-konfiguration" aria-label="Permalink to &quot;Ethernet- och IP-konfiguration&quot;">​</a></h2><h3 id="ip-adress-for-hmi" tabindex="-1">IP-adress för HMI <a class="header-anchor" href="#ip-adress-for-hmi" aria-label="Permalink to &quot;IP-adress för HMI&quot;">​</a></h3><ol><li>I Device configuration, markera HMI:ns <strong>Ethernet-port</strong></li><li>Under <strong>Properties</strong> → <strong>Ethernet addresses</strong></li><li>Konfigurera: <ul><li><strong>IP address:</strong> <code>192.168.0.20</code> (samma subnet som PLC)</li><li><strong>Subnet mask:</strong> <code>255.255.255.0</code></li><li><strong>Use router:</strong> Endast om routing behövs</li><li><strong>Router address:</strong> Gateway (om tillämpligt)</li></ul></li></ol><h3 id="dhcp-eller-statisk-ip" tabindex="-1">DHCP eller statisk IP? <a class="header-anchor" href="#dhcp-eller-statisk-ip" aria-label="Permalink to &quot;DHCP eller statisk IP?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Metod</th><th>Fördelar</th><th>Användning</th></tr></thead><tbody><tr><td><strong>Statisk IP</strong></td><td>Pålitlig, ingen DHCP-server behövs</td><td>Rekommenderas för produktion</td></tr><tr><td><strong>DHCP</strong></td><td>Automatisk tilldelning</td><td>Test och flexibla installationer</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Rekommendation</p><p>Använd <strong>statisk IP</strong> för HMI i produktion. Detta undviker problem med DHCP-lease och säkerställer konsekvent adressering.</p></div><h2 id="runtime-installningar" tabindex="-1">Runtime-inställningar <a class="header-anchor" href="#runtime-installningar" aria-label="Permalink to &quot;Runtime-inställningar&quot;">​</a></h2><h3 id="startskarm-och-uppstart" tabindex="-1">Startskärm och uppstart <a class="header-anchor" href="#startskarm-och-uppstart" aria-label="Permalink to &quot;Startskärm och uppstart&quot;">​</a></h3><ol><li>Under <strong>Runtime settings</strong> → <strong>Screens</strong> → <strong>General</strong></li><li><strong>Start screen:</strong> Välj vilken skärm som visas vid uppstart <ul><li>Oftast &quot;Main&quot; eller &quot;Overview&quot;</li></ul></li><li><strong>Login screen:</strong> Aktivera om inloggning krävs</li></ol><h3 id="larm-och-handelser" tabindex="-1">Larm och händelser <a class="header-anchor" href="#larm-och-handelser" aria-label="Permalink to &quot;Larm och händelser&quot;">​</a></h3><ol><li>Under <strong>Runtime settings</strong> → <strong>Alarms</strong></li><li><strong>Alarm buffering:</strong><ul><li>Antal larm som sparas (t.ex. 1000)</li><li>Aktivera &quot;Store alarms persistently&quot; för att behålla vid strömavbrott</li></ul></li><li><strong>Alarm indication:</strong><ul><li>Ljud vid larm</li><li>Visuell indikering (blinkande)</li></ul></li></ol><h3 id="anvandaradministration" tabindex="-1">Användaradministration <a class="header-anchor" href="#anvandaradministration" aria-label="Permalink to &quot;Användaradministration&quot;">​</a></h3><ol><li>Under <strong>Runtime settings</strong> → <strong>Users</strong></li><li>Skapa användargrupper: <ul><li><strong>Administrators</strong> - Full access</li><li><strong>Operators</strong> - Begränsad access</li><li><strong>Maintenance</strong> - Diagnostik och inställningar</li></ul></li><li>För varje grupp: <ul><li>Definiera behörigheter</li><li>Sätt lösenord</li></ul></li></ol><h2 id="recept-och-data-logging" tabindex="-1">Recept och data logging <a class="header-anchor" href="#recept-och-data-logging" aria-label="Permalink to &quot;Recept och data logging&quot;">​</a></h2><h3 id="recept-recipes" tabindex="-1">Recept (Recipes) <a class="header-anchor" href="#recept-recipes" aria-label="Permalink to &quot;Recept (Recipes)&quot;">​</a></h3><p>Recept låter operatörer spara och ladda parametrar:</p><ol><li>Under <strong>Runtime settings</strong> → <strong>Recipes</strong></li><li>Aktivera &quot;Enable recipes&quot;</li><li>Konfigurera: <ul><li><strong>Storage location:</strong> SD-kort eller intern minne</li><li><strong>Number of recipes:</strong> Max antal recept</li><li><strong>Data records per recipe:</strong> Antal parametrar</li></ul></li></ol><h3 id="data-logging-trends" tabindex="-1">Data logging (Trends) <a class="header-anchor" href="#data-logging-trends" aria-label="Permalink to &quot;Data logging (Trends)&quot;">​</a></h3><p>För att logga processdata över tid:</p><ol><li>Under <strong>Runtime settings</strong> → <strong>Data logs</strong></li><li>Aktivera &quot;Enable data logs&quot;</li><li>Konfigurera: <ul><li><strong>Log interval:</strong> Hur ofta data sparas (1s, 10s, 1min, etc.)</li><li><strong>Storage location:</strong> SD-kort rekommenderas</li><li><strong>Buffer size:</strong> Minnesanvändning</li></ul></li></ol><h2 id="prestanda-och-minneshantering" tabindex="-1">Prestanda och minneshantering <a class="header-anchor" href="#prestanda-och-minneshantering" aria-label="Permalink to &quot;Prestanda och minneshantering&quot;">​</a></h2><h3 id="update-cycle" tabindex="-1">Update cycle <a class="header-anchor" href="#update-cycle" aria-label="Permalink to &quot;Update cycle&quot;">​</a></h3><ol><li>Under <strong>Runtime settings</strong> → <strong>Performance</strong></li><li><strong>Screen update cycle:</strong> Hur ofta skärmen uppdateras (standard 1s) <ul><li>Kortare = snabbare respons, högre CPU-belastning</li><li>Längre = lägre belastning, långsammare respons</li></ul></li><li><strong>Tag update cycle:</strong> Hur ofta taggar läses från PLC (standard 1s)</li></ol><h3 id="minne-och-lagring" tabindex="-1">Minne och lagring <a class="header-anchor" href="#minne-och-lagring" aria-label="Permalink to &quot;Minne och lagring&quot;">​</a></h3><ol><li>Kontrollera tillgängligt minne: <ul><li><strong>Online &amp; Diagnostics</strong> → <strong>Memory</strong></li></ul></li><li>För KTP/TP-paneler med begränsat minne: <ul><li>Begränsa antal skärmbilder</li><li>Använd komprimerade bilder (PNG istället för BMP)</li><li>Undvik för många animationer</li></ul></li></ol><h2 id="sakerhet-och-backup" tabindex="-1">Säkerhet och backup <a class="header-anchor" href="#sakerhet-och-backup" aria-label="Permalink to &quot;Säkerhet och backup&quot;">​</a></h2><h3 id="projektskydd" tabindex="-1">Projektskydd <a class="header-anchor" href="#projektskydd" aria-label="Permalink to &quot;Projektskydd&quot;">​</a></h3><ol><li>Under <strong>Protection</strong> → <strong>Password</strong></li><li>Sätt lösenord för: <ul><li><strong>Full access</strong> - Alla ändringar</li><li><strong>Read-only access</strong> - Endast visa/diagnostik</li></ul></li></ol><h3 id="backup-till-sd-kort" tabindex="-1">Backup till SD-kort <a class="header-anchor" href="#backup-till-sd-kort" aria-label="Permalink to &quot;Backup till SD-kort&quot;">​</a></h3><p>För att automatiskt backupa HMI-projekt:</p><ol><li>Sätt in SD-kort i HMI-panelen</li><li>Under <strong>Runtime settings</strong> → <strong>Backup/Restore</strong></li><li>Aktivera &quot;Automatic backup to SD card&quot;</li><li>Välj intervall (dagligen, veckovis, etc.)</li></ol><h2 id="kompilera-och-ladda-ner-hmi" tabindex="-1">Kompilera och ladda ner HMI <a class="header-anchor" href="#kompilera-och-ladda-ner-hmi" aria-label="Permalink to &quot;Kompilera och ladda ner HMI&quot;">​</a></h2><h3 id="kompilera-hmi-projekt" tabindex="-1">Kompilera HMI-projekt <a class="header-anchor" href="#kompilera-hmi-projekt" aria-label="Permalink to &quot;Kompilera HMI-projekt&quot;">​</a></h3><ol><li>Högerklicka på HMI i projektträdet</li><li>Välj <strong>Compile</strong> → <strong>Software (rebuild all)</strong></li><li>Kontrollera <strong>Info</strong>-fönstret för fel</li><li>Åtgärda eventuella fel</li></ol><h3 id="ladda-ner-till-hmi-panel" tabindex="-1">Ladda ner till HMI-panel <a class="header-anchor" href="#ladda-ner-till-hmi-panel" aria-label="Permalink to &quot;Ladda ner till HMI-panel&quot;">​</a></h3><ol><li>Anslut PC till HMI via Ethernet</li><li>Alternativt: Använd USB-kabel (för direktanslutning)</li><li><strong>Online</strong> → <strong>Download to device</strong></li><li>Välj HMI-panel</li><li>Markera: <ul><li>☑ Hardware configuration</li><li>☑ Software (screens, scripts, etc.)</li></ul></li><li><strong>Load</strong></li><li>HMI startar om automatiskt efter nedladdning</li></ol><h2 id="diagnostik-och-felsokning" tabindex="-1">Diagnostik och felsökning <a class="header-anchor" href="#diagnostik-och-felsokning" aria-label="Permalink to &quot;Diagnostik och felsökning&quot;">​</a></h2><h3 id="online-diagnostik" tabindex="-1">Online-diagnostik <a class="header-anchor" href="#online-diagnostik" aria-label="Permalink to &quot;Online-diagnostik&quot;">​</a></h3><ol><li><strong>Go online</strong> med HMI</li><li><strong>Online &amp; Diagnostics</strong> → <strong>General</strong></li><li>Status-information: <ul><li>Firmware-version</li><li>Minnesanvändning</li><li>Nätverksstatus</li><li>Anslutningar</li></ul></li></ol><h3 id="vanliga-problem" tabindex="-1">Vanliga problem <a class="header-anchor" href="#vanliga-problem" aria-label="Permalink to &quot;Vanliga problem&quot;">​</a></h3><p>❌ <strong>Problem:</strong> HMI kan inte ansluta till PLC ✅ <strong>Lösning:</strong></p><ul><li>Kontrollera IP-adresser (samma subnet?)</li><li>Pinga PLC från HMI-diagnostik</li><li>Kontrollera brandvägg på PC</li></ul><p>❌ <strong>Problem:</strong> &quot;Memory full&quot; ✅ <strong>Lösning:</strong></p><ul><li>Ta bort oanvända skärmbilder</li><li>Komprimera bilder</li><li>Öka clearing-intervall för larm</li></ul><p>❌ <strong>Problem:</strong> Långsam uppdatering ✅ <strong>Lösning:</strong></p><ul><li>Öka update cycle-tid</li><li>Reducera antal aktiva taggar</li><li>Använd &quot;Update on change&quot; istället för cyklisk uppdatering</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><p>✅ <strong>Strukturera ditt HMI-projekt</strong></p><ul><li>Skapa en logisk skärmhierarki</li><li>Använd globala skärmmallar (templates)</li><li>Konsekvent färgschema och knapputseende</li></ul><p>✅ <strong>Optimera prestanda</strong></p><ul><li>Använd bara nödvändiga taggar</li><li>Begränsa antal aktiva animationer</li><li>Cachea bilder och grafikelement</li></ul><p>✅ <strong>Säkerhet</strong></p><ul><li>Aktivera användaradministration</li><li>Sätt lösenord på kritiska funktioner</li><li>Logga användaråtgärder</li></ul><h2 id="resurser-och-dokumentation" tabindex="-1">Resurser och dokumentation <a class="header-anchor" href="#resurser-och-dokumentation" aria-label="Permalink to &quot;Resurser och dokumentation&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/108716692" target="_blank" rel="noreferrer">WinCC Comfort/Advanced System Manual</a> - Komplett manual</li><li><a href="https://support.industry.siemens.com/cs/document/93703241" target="_blank" rel="noreferrer">HMI Connection to S7-1200</a> - Anslutningsguide</li></ul><h3 id="video-tutorials" tabindex="-1">Video-tutorials <a class="header-anchor" href="#video-tutorials" aria-label="Permalink to &quot;Video-tutorials&quot;">​</a></h3><ul><li>YouTube: &quot;TIA Portal HMI configuration&quot;</li><li>YouTube: &quot;WinCC HMI connection setup&quot;</li><li>YouTube: &quot;TIA Portal HMI download&quot;</li></ul><div class="tip custom-block"><p class="custom-block-title">Nästa steg</p><p>Nu när HMI är konfigurerad, fortsätt med <a href="./frekvensomriktare-profinet.html">Frekvensomriktare via Profinet</a> för att lära dig styra frekvensomriktare.</p></div>',81)])])}const p=a(e,[["render",l]]);export{h as __pageData,p as default};
